import React, { useEffect, useState } from 'react';
import './Header.css';  // Make sure to import the CSS for the Header component

const Header = () => {
	const [headerStyle, setHeaderStyle] = useState({});

	useEffect(() => {
		const handleScroll = () => {
			const scrollProgress = Math.min(window.scrollY / 100, 1); // Ensure the value is between 0 and 1
			// Apply the desired effects based on scroll progress
			setHeaderStyle({
				opacity: scrollProgress, // Adjust opacity based on scroll progress
				backgroundColor: `rgba(255, 250, 241, ${scrollProgress * 0.712})`, // Transition to the target background color
				backdropFilter: `blur(${Math.min(5 * scrollProgress, 5)}px)`, // Apply blur effect based on scroll progress
				WebkitBackdropFilter: `blur(${Math.min(5 * scrollProgress, 5)}px)`, // For Safari
				boxShadow: `0 4px 30px rgba(0, 0, 0, ${scrollProgress * 0.1})`, // Apply box-shadow based on scroll progress
			});
		};

		window.addEventListener('scroll', handleScroll);

		// Cleanup function to remove the event listener
		return () => window.removeEventListener('scroll', handleScroll);
	}, []);

	return (
		<header id='header' style={headerStyle}>
			<nav>
				<ul>
					<li><a href="#intro">Intro</a></li>
					<li><a href="#about">About Me</a></li>
					<li><a href="#skills">Skills</a></li>
					<li><a href="#contact">Contact</a></li>
				</ul>
			</nav>
		</header>
	);
};
